const listify=v=>Array.isArray(v)?v:[];
function fieldValueLabel(id,value){const f=FORM.flatMap(s=>s.fields).find(f=>f.id===id);if(Array.isArray(value))return value.map(x=>f?.options.find(o=>o[0]===x)?.[1]||x).join('، ');return f?.options.find(o=>o[0]===String(value))?.[1]||String(value??'')}
function missingProfile(p=state.profile){const missing=FORM.flatMap(s=>s.fields).filter(f=>f.required&&!(f.type==='consent'?p[f.id]===true:f.type==='multi'?listify(p[f.id]).length:f.type==='money'?p[f.id]!==''&&p[f.id]!=null&&Number.isFinite(num(p[f.id]))&&num(p[f.id])>=0:String(p[f.id]??'').trim())).map(f=>f.id);if(p.allergyStatus==='yes'&&!String(p.allergies||'').trim())missing.push('allergies');if(p.medicationStatus==='yes'&&!String(p.medications||'').trim())missing.push('medications');return missing}
function completion(p=state.profile){const total=FORM.flatMap(s=>s.fields).filter(f=>f.required).length;return Math.max(0,Math.round(100*(total-missingProfile(p).length)/total))}
function readDraft(){if(!wizardDraft)wizardDraft=structuredClone(state.profileDraft||state.profile);return wizardDraft}
function qHtml(f,p){const value=p[f.id],required=f.required?' <span aria-label="لازم">*</span>':'';let input='';if(f.type==='select')input=`<select id="pf-${f.id}" name="${f.id}"><option value="">انتخاب کن…</option>${f.options.map(([k,v])=>`<option value="${k}" ${String(value)===k?'selected':''}>${esc(v)}</option>`).join('')}</select>`;else if(f.type==='multi')input=`<div class="choice-grid">${f.options.map(([k,v])=>`<label><input type="checkbox" name="${f.id}" value="${k}" ${listify(value).includes(k)?'checked':''}>${esc(v)}</label>`).join('')}</div>`;else if(f.type==='consent')input=`<div class="choice-grid"><label><input type="checkbox" name="${f.id}" ${value===true?'checked':''}>موافقم</label></div>`;else if(f.type==='textarea')input=`<textarea id="pf-${f.id}" name="${f.id}" rows="3" maxlength="1500">${esc(value||'')}</textarea>`;else input=`<input id="pf-${f.id}" name="${f.id}" value="${esc(value??'')}" ${f.type==='money'?'inputmode="numeric"':'maxlength="220"'}>`;return `<div class="question"><label for="pf-${f.id}">${f.label}${required}</label>${f.help?`<small>${f.help}</small>`:''}${input}</div>`}
function saveDraft(form){const p=readDraft(),fd=new FormData(form);for(const f of FORM[wizardStep].fields){if(f.type==='multi')p[f.id]=fd.getAll(f.id);else if(f.type==='consent')p[f.id]=fd.has(f.id);else p[f.id]=fd.get(f.id)??p[f.id]}state.profileDraft=structuredClone(p);if(p.consent)persist()}
function wizardValidation(){const p=readDraft(),stageIds=FORM[wizardStep].fields.map(f=>f.id),missing=missingProfile(p).filter(id=>stageIds.includes(id));if(missing.length)return 'این موارد رو تکمیل کن: '+missing.map(id=>FORM.flatMap(s=>s.fields).find(f=>f.id===id)?.label||id).join('، ');for(const id of ['budget','purchaseCap','shipping'])if(stageIds.includes(id)&&p[id]!==''&&(!Number.isFinite(num(p[id]))||num(p[id])<0))return 'مبلغ باید عدد معتبر و غیرمنفی باشد.';return ''}
profile=function(){const p=readDraft(),step=FORM[wizardStep];return `<span class="eyebrow">پروفایل شخصی من</span><h1>یک بار بگو؛ یادم می‌مونه.</h1><div class="row between"><small>مرحله ${fa(wizardStep+1)} از ${fa(FORM.length)}</small><span class="phase-label">${fa(completion(p))}٪ پرسش‌های اصلی پاسخ داده شده</span></div><div class="wizard-progress"><i style="width:${completion(p)}%"></i></div><div class="wizard-tabs" role="tablist">${FORM.map((s,i)=>`<button type="button" role="tab" aria-selected="${i===wizardStep}" data-wizard-step="${i}" class="${i===wizardStep?'selected':''}">${s.title}</button>`).join('')}</div><form id="profileWizard" class="card" novalidate><h2>${step.title}</h2><p class="wizard-help">${step.intro}</p>${step.fields.map(f=>qHtml(f,p)).join('')}${wizardStep===3?`<section class="notice"><b>${fa(state.wallet.length)} محصول در ولت ثبت شده</b><p>نام دقیق، مرحله، دفعات مصرف و ترکیبات هر محصول را وارد کن.</p><button type="button" data-v8="add-wallet">＋ ثبت محصول فعلی</button></section>`:''}${wizardStep===6?profileSummary(p):''}<p id="profileError" class="profile-error" role="alert"></p><div class="wizard-footer">${wizardStep?'<button type="button" data-wizard-prev>قبلی</button>':'<button type="button" data-view="home">بعداً ادامه می‌دم</button>'}<button class="gold" type="submit">${wizardStep===6?'ذخیره پروفایل من ✓':'ذخیره و ادامه ←'}</button></div></form><p class="local-note">اطلاعات در همین مرورگر می‌ماند. برای انتقال به گوشی دیگر یا نگهداری مطمئن، پشتیبان بگیر. تغییر بارداری، دارو یا علائم را به‌روز کن.</p><div class="row"><button data-v8="backup">دریافت پشتیبان</button><button data-v8="restore">بازیابی فایل</button><button data-v8="erase" class="remove">حذف اطلاعات من</button></div>`};
function profileSummary(p){return `<div>${['name','age','skinType','skinToday','goal','sensitivity','pregnancy','allergyStatus','medicationStatus','amTime','pmTime','maxSteps','budget','brands'].map(id=>`<div class="summary-line"><span>${esc(FORM.flatMap(s=>s.fields).find(f=>f.id===id)?.label||id)}</span><b>${esc(fieldValueLabel(id,p[id])||'پاسخ داده نشده')}${id==='budget'?' تومان':''}</b></div>`).join('')}</div><div class="notice">${missingProfile(p).length?'هنوز چند سؤال اصلی پاسخ داده نشده؛ از بالای صفحه به همان مرحله برگرد.':'پرسش‌های اصلی کامل است. این وضعیت به معنی تشخیص پوست یا تأیید پزشکی نیست.'}${p.routineKnown==='yes'&&!state.wallet.length?'<br>محصولات فعلی را هم در ولت وارد کن؛ بدون آن‌ها تحلیل کل روتین کامل نمی‌شود.':''}</div>`}
home=function(){return window.BW_HOME_TEMPLATE};
function updateHome(){if(route!=='home')return;const p=state.profile,nudge=$('#profileNudge');if(nudge)nudge.innerHTML=`<div class="profile-nudge"><p><b>${p.completedAt?'پروفایلت یادم هست، '+esc(p.name||'دوست من'):'اول تو رو بشناسم؟'}</b><br>${p.completedAt?'پوست '+esc(skins[p.skinType]||'نامشخص')+' · هدف '+esc(goals[p.goal]||'ثبت نشده')+' · '+fa(state.wallet.length)+' محصول در ولت':'پوست، سلیقه و بودجه‌ات رو یک بار ثبت کن.'}</p><button class="gold" data-view="profile">${p.completedAt?'مشاهده و به‌روزرسانی پروفایل':'ساخت پروفایل شخصی'}</button></div>`;const set=(s,t)=>{if($(s))$(s).textContent=t};set('#budgetSpentText',fa(spent())+' تومان');set('#budgetTotalText','از '+fa(p.budget)+' تومان');const percent=Math.min(100,Math.round(spent()/Math.max(1,p.budget)*100));set('#budgetPercent',fa(percent)+'٪');if($('#budgetProgress'))$('#budgetProgress').style.width=percent+'%';set('#savingsText',fa(remaining())+' تومان از بودجه باقی مانده. هزینه ارسال را هم در نظر بگیر.');const strip=$('.reference-home .product-strip');if(state.wallet.length&&strip)strip.innerHTML=state.wallet.slice(0,3).map(w=>`<button class="mini-product" data-v8-wallet="${esc(w.id)}"><div class="blank-art" aria-hidden="true">${({protect:'☀',cleanse:'◌',moisturize:'◡'})[w.role]||'◇'}</div><b>${esc(w.name)}</b><small>${fa(w.remaining)}٪ باقی‌مانده</small></button>`).join('')+'<button class="mini-product add" data-v8="add-wallet"><span>＋</span><b>محصول جدید</b><small>اضافه کن</small></button>';else if(strip){strip.querySelectorAll('article').forEach(el=>{const sm=el.querySelector('small');if(sm)sm.textContent+=' · نمونه'});const title=$('.reference-home .wallet-card .section-title p');if(title)title.textContent='تصاویر نمونه؛ محصول واقعی خودت را اضافه کن.'}const timeline=$('.reference-home .timeline-images');if(state.outcomes.length&&timeline)timeline.innerHTML=state.outcomes.slice(-3).map(o=>`<figure>${o.photo?`<img src="${esc(o.photo)}" alt="عکس ثبت‌شده شخصی">`:'<div class="blank-art">♡</div>'}<figcaption><b>${new Date(o.date).toLocaleDateString('fa-IR')}</b><small>رضایت ${fa(o.rating)} از ۵</small></figcaption></figure>`).join('');set('#nextMove',!p.completedAt?'پروفایل را کامل کن تا پیشنهادها مخصوص خودت شوند.':!state.wallet.length?'محصولات فعلیت را ثبت کن؛ قبل از خرید، داشته‌ها مهم‌اند.':owned('protect')?'روتین ساده امروز را انجام بده و نتیجه را ثبت کن.':'قبل از سرم جدید، وضعیت محافظت از آفتاب را بررسی کن.');const demo=$('.reference-home .decision-demo');if(demo){const b=document.createElement('button');b.className='outline-gold';b.dataset.view='products';b.textContent='بررسی محصول خودم';b.style.gridColumn='1 / -1';demo.appendChild(b)}}
const baseFit=fit;
function productGate(p){const reasons=[],profile=state.profile,meta=state.productMeta[p.id]||{},formula=String(meta.inci||''),search=norm(p.nameFa+' '+formula);if(missingProfile(profile).length)reasons.push('پروفایل هنوز کامل نیست');if(profile.routineKnown==='yes'&&!state.wallet.length)reasons.push('محصولات فعلی روتین ثبت نشده‌اند');if(profile.pregnancy&&profile.pregnancy!=='no')reasons.push('شرایط بارداری/شیردهی یا نامشخص بودن آن نیاز به بررسی دارد');if(profile.age==='under18')reasons.push('برای زیر ۱۸ سال، مراقبت باید متناسب با سن بررسی شود');if(listify(profile.currentSymptoms).some(x=>['burn','severe'].includes(x)))reasons.push('علائم فعال تحریک ثبت شده است');if(profile.medicationStatus&&profile.medicationStatus!=='no')reasons.push('درمان فعلی یا نامشخص بودن آن باید در ارزیابی لحاظ شود');if(profile.allergyStatus&&profile.allergyStatus!=='no'&&!formula)reasons.push('برای حساسیت ثبت‌شده یا نامشخص، ترکیبات کافی نداریم');const allergies=String(profile.allergies||profile.avoid||'').split(/[,،\n]/).map(norm).filter(x=>x.length>2);if(formula&&allergies.some(x=>norm(formula).includes(x)))reasons.push('تطبیق احتمالی با حساسیت ثبت‌شده؛ بررسی حرفه‌ای لازم است');if(!p.formulaVerified)reasons.push('ترکیبات نسخه بازار تأیید نشده');if(p.status==='conflicted')reasons.push('بین مشخصات منابع تعارض وجود دارد');return reasons}
fit=function(p){const f=baseFit(p),profile=state.profile,meta=state.productMeta[p.id];const goalMatch=(profile.goal==='barrier'&&p.role==='moisturize')||(profile.goal==='prevention'&&p.role==='protect')||(profile.goal==='spots'&&(p.tags||[]).includes('brightening'))||(profile.goal==='acne'&&(p.tags||[]).some(t=>['acne','sebum'].includes(t)));if(goalMatch){f.score+=2;f.reasons.push('کاربرد درج‌شده با هدف اصلی‌ات مرتبط است؛ تأیید اثر نیست')}if(String(profile.pastBad||'').length>2&&(norm(profile.pastBad).includes(norm(p.nameFa))||norm(profile.pastBad).includes(norm(p.brand)))){f.score-=10;f.reasons.push('این برند یا محصول در تجربه نامطلوبت آمده')}if(meta?.texture&&profile.texture!=='any'&&profile.texture===meta.texture){f.score+=2;f.reasons.push('بافت ثبت‌شده با ترجیحت هم‌خوان است')}if(profile.fragrance==='free'&&meta?.fragrance==='yes'){f.score-=5;f.reasons.push('طبق ثبت شما رایحه دارد؛ با ترجیحت هم‌خوان نیست')}if(profile.sunExposure==='high'&&p.role==='protect'){f.score+=2;f.reasons.push('برای مواجهه زیاد با آفتاب، بررسی این نقش اولویت دارد')}return f};
price=function(p){const q=oldPrice(p);if(!q)return null;const age=Date.now()-Date.parse(q.date);return {...q,fresh:q.kind==='user'&&age>=0&&age<86400000&&q.stock!=='no'&&Number.isFinite(q.value)&&q.value>0}};
function availableBudget(){const p=state.profile,monthly=Math.max(0,remaining()-Math.max(0,num(p.shipping)||0));return p.purchaseCap!==''&&p.purchaseCap!=null?Math.min(monthly,Math.max(0,num(p.purchaseCap)||0)):monthly}
const basicRoles=['protect','cleanse','moisturize'];
basket=function(){let left=availableBudget(),total=0;const chosen=[],unresolved=[],issues=[];for(const role of basicRoles){if(owned(role))continue;const list=catalog.filter(p=>p.role===role&&price(p)?.fresh&&price(p).value<=left&&!fit(p).bad&&((p.skinTypes||[]).includes(state.profile.skinType)||(p.skinTypes||[]).includes('all'))).sort((a,b)=>fit(b).score-fit(a).score||price(a).value-price(b).value);if(list.length){const p=list[0];chosen.push(p);total+=price(p).value;left-=price(p).value;issues.push(...productGate(p))}else unresolved.push(roles[role])}return {chosen,total,left,unresolved,issues:[...new Set(issues)],shipping:num(state.profile.shipping)||0}};
function contextLine(){const p=state.profile,parts=[];if(p.name)parts.push(p.name+' جان');if(p.skinType&&p.skinType!=='unknown')parts.push('پوست '+(skins[p.skinType]||p.skinType));if(p.goal)parts.push('هدفت '+(goals[p.goal]||p.goal));if(p.amTime&&p.pmTime)parts.push('صبح '+fa(p.amTime)+' و شب '+fa(p.pmTime)+' دقیقه وقت داری');parts.push(fa(state.wallet.length)+' محصول ثبت کردی');return parts.join(' · ')}
function sourceHtml(ids){return [...new Set(ids||[])].map(id=>KB.sources.find(s=>s.id===id)).filter(Boolean).map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.title)}</a>`).join(' · ')}
function makeReply(title,text,action='',sources=[],buttons=[],extra={}){return {role:'assistant',id:uid(),title,text,action,sources,buttons,context:contextLine(),date:new Date().toISOString(),...extra}}
function findCandidates(q){const n=norm(q),exact=catalog.filter(p=>norm(p.nameFa)===n||(p.lookupTokens||[]).some(t=>norm(t)===n));if(exact.length)return exact;return catalog.filter(p=>n.includes(norm(p.brand))||norm(p.nameFa).includes(n)&&n.length>3)}
function profileMemoryText(){const p=state.profile;return `${p.name?'اسمت '+p.name+' است.\n':''}پوست: ${skins[p.skinType]||'هنوز مطمئن نیستی'}\nهدف: ${goals[p.goal]||'ثبت نشده'}\nبودجه ماهانه: ${fa(p.budget)} تومان؛ باقی‌مانده: ${fa(remaining())} تومان\nبافت محبوب: ${fieldValueLabel('texture',p.texture)||'ثبت نشده'}\nبرندها: ${p.brands||'هنوز نگفتی'}\nمحصولات ولت: ${state.wallet.map(w=>w.name).join('، ')||'خالی'}\nاگر چیزی تغییر کرده، فقط همان بخش را ویرایش کن.`}
function quoteSummary(p){const q=price(p);return !q?'قیمت فعلی نامشخص':fa(q.value)+' تومان؛ '+(q.fresh?'ثبت تازه شما':'قیمت تاریخی / نیازمند به‌روزرسانی')}
function comparisonReply(p){const r=fit(p),alternatives=catalog.filter(x=>x.id!==p.id&&x.role===p.role).sort((a,b)=>fit(b).score-fit(a).score).slice(0,3);return makeReply('جایگزین رو با دلیل انتخاب کنیم ♡',`${p.nameFa}\n${quoteSummary(p)}\n\n${owned(p.role)?'این نقش همین حالا در ولتت موجود است؛ اول ببین واقعاً جایگزینی لازم داری یا نه.':'این نقش در ولت فعلیت کامل ثبت نشده.'}\n\nگزینه‌های هم‌نقش برای بررسی:\n${alternatives.map((x,i)=>(i+1)+'۔ '+x.nameFa+'\n'+quoteSummary(x)+'\n'+(fit(x).reasons[0]||'نیاز به بررسی مشخصات')).join('\n\n')}`,'هم‌نقش بودن، هم‌ارزی فرمول یا مناسب بودن برای پوست تو را ثابت نمی‌کند.',['aad-basic'],alternatives.map(x=>({label:x.brand+' · بررسی',kind:'product',id:x.id})),{productId:p.id})}
function budgetReply(){const b=basket();let text=`از بودجه این ماه ${fa(remaining())} تومان مانده. با کنارگذاشتن ${fa(b.shipping)} تومان برای ارسال و سقف هر خرید، ${fa(availableBudget())} تومان قابل برنامه‌ریزی است.\n\n`;if(!b.chosen.length&&!b.unresolved.length)text+='نقش‌های پایه را در ولت داری؛ فعلاً برای کامل‌کردن آن‌ها خرید لازم نیست.';else if(!b.chosen.length)text+='فعلاً قیمت تازه و گزینه کافی برای سبد قابل اتکا نداریم؛ قیمت نامشخص را به‌جای صفر نمی‌گذارم.';else text+='سبد محاسباتی برای بررسی:\n'+b.chosen.map(p=>'• '+p.nameFa+' — '+fa(price(p).value)+' تومان').join('\n')+'\nجمع محصول‌ها: '+fa(b.total)+' تومان\nبا ذخیره ارسال: '+fa(b.total+b.shipping)+' تومان';if(b.unresolved.length)text+='\n\nسبد کامل نیست؛ برای '+b.unresolved.join('، ')+' قیمت تازه یا گزینه در بودجه نداریم.';if(b.issues.length)text+='\n\nتأیید خرید صادر نمی‌کنم: '+b.issues.join('؛ ')+'.';return makeReply('بذار پولت جای درست خرج بشه ✦',text,'قیمت دقیق محصول را با لینک فروشنده ثبت کن تا محاسبه بهتر شود. هزینه ارسال ثبت‌شده برآورد خودت است.',['aad-basic'],[{label:'دیدن محصولات و ثبت قیمت',kind:'view',id:'products'},{label:'ویرایش بودجه',kind:'profile',id:'5'}])}
function routineReply(){const p=state.profile,am=[owned('moisturize')?.name||'مرطوب‌کننده قابل تحمل فعلی‌ات',owned('protect')?.name||'ضدآفتاب مناسب با برچسب کامل'],pm=[owned('cleanse')?.name||'شوینده ملایم',owned('moisturize')?.name||'مرطوب‌کننده قابل تحمل فعلی‌ات'];return makeReply('یه روتین که واقعاً انجامش بدی 🌿',`صبح${p.amTime?'؛ زمان مطلوب '+fa(p.amTime)+' دقیقه':''}:\n۱۔ ${am[0]}\n۲۔ ${am[1]}\n\nشب${p.pmTime?'؛ زمان مطلوب '+fa(p.pmTime)+' دقیقه':''}:\n۱۔ ${pm[0]}\n۲۔ ${pm[1]}\n\n${p.makeup==='waterproof'?'برای پاک‌کردن آرایش مقاوم به آب، دستور پاک‌کننده‌ات را رعایت کن.\n':''}${p.medicationStatus==='yes'?'درمان تجویزشده‌ات مرحله جداست؛ آن را حذف یا جابه‌جا نمی‌کنم.\n':''}${listify(p.barrierReason).includes('forget')?'برای فراموشی، انجام شب را به یک عادت ثابت مثل مسواک وصل کن؛ این یک پیشنهاد رفتاری است.\n':''}اسم‌های ثبت‌نشده، نقش عمومی‌اند و توصیه یک محصول خاص نیستند.`,'زمان‌ها هدف تو هستند، نه زمان تضمینی اجرا. مقدار مصرف و تجدید ضدآفتاب طبق برچسب مهم است.',['aad-basic','aad-sun'],[{label:'دیدن و تیک‌زدن روتین',kind:'view',id:'routine'}])}
function inferBudget(q){let t=String(q).replace(/[۰-۹]/g,c=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(c));const m=t.match(/([\d.,٬]+)\s*(میلیون|هزار)?/);if(!m)return null;let value=num(m[1]);if(m[2]==='میلیون')value*=1e6;if(m[2]==='هزار')value*=1000;if(/ریال/.test(t))value/=10;return Number.isFinite(value)&&value>=0?value:null}
function richAnswer(q){const n=norm(q),p=state.profile;
 if(/تنگینفس|نفسمبالا|تورم(?:زبان|گلو)|بیهوش/.test(n))return makeReply('این علامت نیاز به کمک فوری دارد', 'اگر الان مشکل تنفس، تورم زبان یا گلو یا حالت غش داری، با اورژانس محل تماس بگیر یا فوری کمک پزشکی بگیر. اینجا بررسی محصول یا خرید را ادامه نده.','در ایران شماره اورژانس ۱۱۵ است. اگر جای دیگری هستی از شماره محلی استفاده کن.',[],[]);
 if(/سوزشدارم|پوستممیسوزه|صورتممیسوزه|تاولزده|ورمکرده|متورمشده/.test(n))return makeReply('فعلاً محصول تازه اضافه نکن', 'اگر این واکنش بعد از محصول جدید شروع شده، مصرف همان محصول را متوقف کن. با علائم شدید، گسترش سریع، درگیری چشم یا علائم ماندگار، ارزیابی پزشکی لازم است. از این پیام نمی‌تونم تشخیص بدم.','نام محصول، زمان شروع و علائم را در نتیجه مصرف ثبت کن.',['aad-moisture'],[{label:'ثبت تجربه مصرف',kind:'view',id:'wallet'}]);
 if(/^(سلام|سلامخوبی|های|hello|hi|درود)[!؟?]*$/.test(n))return makeReply(p.name?`سلام ${p.name} جان ♡`:'سلام، خوش اومدی ♡',p.completedAt?'پروفایلت یادمه. امروز روتین رو ساده کنیم، یه خرید رو بررسی کنیم یا درباره یک ترکیب حرف بزنیم؟':'قبل از پیشنهاد شخصی، دوست دارم پوست و شرایطت رو بشناسم. می‌تونی پروفایل رو مرحله‌ای تکمیل کنی؛ جواب‌هات می‌مونن.','از همین سه مسیر شروع کنیم.',[],[{label:'روتین کوتاه',kind:'ask',id:'روتینم رو کوتاه کن'},{label:'بررسی بودجه',kind:'ask',id:'با بودجه‌ام چی بخرم؟'},{label:'پروفایل من',kind:'view',id:'profile'}]);
 if(/چی(?:ازمن)?یادته|چیازمنمیدونی|پروفایلم|اطلاعاتمن|منومیشناسی/.test(n))return makeReply('این‌ها رو از خودت می‌دونم',profileMemoryText(),'اطلاعات تو برای آموزش مدل ارسال نشده؛ در همین مرورگر نگه داشته می‌شود.',[],[{label:'ویرایش پروفایل',kind:'view',id:'profile'}]);
 if(/بودج/.test(n)&&/تغییر|بذار|بزار|شد|هست|دارم|میلیون|هزار|\d|[۰-۹]/.test(q)){const v=inferBudget(q);if(v!==null)return makeReply('بودجه‌ات رو به‌روز کنم؟',`منظورت ${fa(v)} تومان به‌عنوان سقف خرید ماهانه است؟ تا تأیید نکنی، بودجه قبلی را نگه می‌دارم.`,'اگر این مبلغ فقط برای همین خرید است، سقف هر خرید را در پروفایل تغییر بده.',[],[{label:'بله، '+fa(v)+' تومان',kind:'budget',id:String(v)},{label:'خودم تنظیم می‌کنم',kind:'profile',id:'5'}])}
 if(/بودجه|ارزان|ارزون|اقتصادی|چقدرپول|چی(?:رو)?بخرم|چه(?:چیزی|محصولی)بخرم/.test(n))return budgetReply();
 if(/کوتاه|روتینم|روتینبده|وقتندارم|حوصلهندارم|مراحلروتین/.test(n))return routineReply();
 if(/چیزهایی(?:که)?دارم|چی(?:توی)?کیف|کیفم/.test(n))return makeReply('اول داشته‌هات رو ببینیم',state.wallet.length?state.wallet.map(w=>w.name+' — '+fa(w.remaining)+'٪ باقی‌مانده').join('\n'):'هنوز محصولی در ولت ثبت نکردی؛ با نام دقیق محصول شروع کن.','داشتن محصول با نقش مشابه معمولاً دلیل خوبی است که خرید تکراری را عقب بیندازیم.',['aad-basic'],[{label:'بازکردن ولت',kind:'view',id:'wallet'}]);
 if(/مشابه|جایگزین|مقایسه|اینروبخرم|اینوبخرم|محصول/.test(n)||findCandidates(q).length){let candidates=findCandidates(q);if(!candidates.length&&state.recentQuestion?.productId&&/این|همون|ارزون|جایگزین/.test(n))candidates=catalog.filter(x=>x.id===state.recentQuestion.productId);if(candidates.length===1)return comparisonReply(candidates[0]);if(candidates.length>1)return makeReply('کدوم نسخه محصول رو می‌گی؟','این برند چند محصول دارد و نمی‌خوام نسخه اشتباه را بررسی کنم. محصول دقیق را انتخاب کن.','نام، حجم و نسخه محصول مهم‌اند.',[],candidates.slice(0,4).map(x=>({label:x.nameFa,kind:'compare',id:x.id})));if(/مشابه|جایگزین|مقایسه|بخرم/.test(n))return makeReply('اسم دقیقش رو بگو تا اشتباه نکنیم','نام کامل، لینک یا بارکد محصول رو بفرست. اگر در فهرست نباشه می‌تونی عکس بسته و ترکیبات رو ثبت کنی.','از اسم برند به‌تنهایی فرمول و قیمت را حدس نمی‌زنم.',[],[{label:'جست‌وجوی محصول',kind:'view',id:'products'},{label:'ثبت محصول ناشناخته',kind:'intake',id:''}])}
 const scored=KB.topics.map(t=>({t,score:t.keywords.reduce((a,k)=>a+(n.includes(norm(k))?Math.max(2,norm(k).length):0),0)})).filter(x=>x.score>0).sort((a,b)=>b.score-a.score);if(scored.length){const best=scored[0].t;let text=best.text;if(best.id==='pregnancy'&&p.pregnancy==='no')text+='\nاین پاسخ اطلاعات عمومی است؛ در پروفایلت این شرایط را ثبت نکرده‌ای.';if(best.id==='dry'&&p.skinType==='oily')text+='\nچون پوستت را چرب ثبت کردی، چربی و حس خشکی را جدا از هم پیگیری کنیم.';if(['retinol','acne','niacinamide'].includes(best.id)&&p.medicationStatus==='yes')text+='\nدرمان فعلی ثبت کردی؛ قبل از افزودن فعال جدید، آن را با پزشک یا داروساز مرور کن.';if(['retinol','acne'].includes(best.id)&&p.pregnancy&&p.pregnancy!=='no')text+='\nوضعیت بارداری/شیردهی در پروفایلت نیازمند احتیاط است؛ تأیید مصرف صادر نمی‌کنم.';const secondary=scored[1]?.t;if(secondary&&secondary.id!==best.id&&scored[1].score>=6&&['pregnancy','sensitive'].includes(secondary.id))text+='\n\n'+secondary.text;return makeReply(best.title+' ✦',text,best.action,[...best.sources,...(secondary&&['pregnancy','sensitive'].includes(secondary.id)?secondary.sources:[])],[{label:'منابع و محدودیت‌ها',kind:'sources',id:best.sources.join(',')},{label:'بررسی روتین من',kind:'view',id:'routine'}],{topicId:best.id})}
 if(/ادامه|بیشتر|چرا|توضیح|منبع/.test(n)&&state.recentQuestion?.topicId){const t=KB.topics.find(t=>t.id===state.recentQuestion.topicId);if(t)return makeReply('یه کم دقیق‌تر درباره '+t.title,t.text+'\n\n'+t.sources.map(id=>{const s=KB.sources.find(x=>x.id===id);return s.summary+'\nمحدودیت: '+s.limit}).join('\n\n'),t.action,t.sources)}
 if(/ممنون|مرسی|دمتگرم|تشکر/.test(n))return makeReply('خواهش می‌کنم ♡','هر وقت خواستی، با یک تغییر کوچک ادامه می‌دیم. لازم نیست روتین پیچیده‌ای بسازی.','می‌تونی انجام روتین امروز رو ثبت کنی.',[],[{label:'روتین امروز',kind:'view',id:'routine'}]);
 return makeReply('این سؤال رو نمی‌خوام حدسی جواب بدم','برای این پرسش، پاسخ کافی در دانش بررسی‌شده فعلی پیدا نکردم. فعلاً می‌تونم درباره روتین پایه، خشکی، پوست چرب، نیاسینامید، ضدآفتاب، احتیاط‌های درمان و بودجه کمک کنم.','اگر منظورت محصول خاصی است، نام دقیق یا ترکیباتش را بفرست. پاسخ آزاد مدل زبانی هنوز فعال نشده.',[],[{label:'دیدن دانش و منابع',kind:'sources',id:''},{label:'کامل‌کردن پروفایل',kind:'view',id:'profile'}]);
}
function replyHtml(m){if(m.role==='user')return `<div class="bubble user"><p>${esc(m.text)}</p></div>`;return `<article class="bubble assistant">${m.title?`<h3>${esc(m.title)}</h3>`:''}${m.context?`<p class="context-note">${esc(m.context)}</p>`:''}<p>${esc(m.text)}</p>${m.action?`<p class="next-action"><b>قدم بعدی تو:</b> ${esc(m.action)}</p>`:''}${m.sources?.length?`<div class="reply-source">منبع پاسخ: ${sourceHtml(m.sources)}</div>`:''}<div class="row">${(m.buttons||[]).map(b=>`<button data-chat-kind="${esc(b.kind)}" data-chat-id="${esc(b.id)}">${esc(b.label)}</button>`).join('')}</div>${m.id?`<div class="response-feedback"><button data-feedback="${esc(m.id)}" data-rating="yes" aria-label="پاسخ مفید بود">${state.feedback.some(f=>f.id===m.id&&f.rating==='yes')?'✓ ':''}مفید بود</button><button data-feedback="${esc(m.id)}" data-rating="no">${state.feedback.some(f=>f.id===m.id&&f.rating==='no')?'✓ ':''}به دردم نخورد</button></div>`:''}</article>`}
assistant=function(){const p=state.profile;return `<span class="eyebrow">همراه مراقبت و خرید تو</span><h1>امروز از کجا شروع کنیم؟</h1><div class="profile-capsule">${esc(contextLine())}<br><button data-view="profile">${p.completedAt?'ویرایش اطلاعات من':'تکمیل پروفایل'}</button></div><div class="chat-prompts">${['روتینم رو کوتاه کن','با بودجه‌ام چی بخرم؟','نیاسینامید لازم دارم؟','چی از من می‌دونی؟'].map(q=>`<button data-ask="${q}">${q}</button>`).join('')}</div><section id="chat" class="chat" aria-live="polite">${state.chat.length?state.chat.map(replyHtml).join(''):replyHtml(makeReply(p.name?'سلام '+p.name+' جان ♡':'سلام، خوش اومدی ♡','با اطلاعات پروفایلت، ولت و منابع بررسی‌شده جواب می‌دم. دوست داری خریدی رو بررسی کنیم یا روتینت رو سبک‌تر کنیم؟','از گزینه‌های بالا شروع کن.',[],[]))}</section><form id="chatForm" class="chatForm"><label class="sr-only" for="message">پیام به دستیار</label><div class="fieldrow"><textarea id="message" rows="2" maxlength="2000" placeholder="مثلاً پوست چربم چرا حس کشیدگی داره؟" required></textarea><button class="gold" type="submit">ارسال ↑</button></div></form><p class="local-note">حالت آفلاین منبع‌دار · ${fa(KB.sources.length)} منبع · مدل زبانی آزاد هنوز متصل نیست. تاریخ مرور دانش: ${new Date(KB.version+'T12:00:00').toLocaleDateString('fa-IR')}</p><div class="row"><button data-v8="sources">دانش و منابع</button><button data-v8="clear-chat">پاک‌کردن گفتگو</button></div>`};
ask=function(q){if(!String(q).trim())return;const text=String(q).trim().slice(0,2000),reply=richAnswer(text);state.chat.push({id:uid(),role:'user',text,date:new Date().toISOString()},reply);state.recentQuestion={productId:reply.productId||null,topicId:reply.topicId||null};persist();go('assistant');if($('#chat'))$('#chat').scrollTop=$('#chat').scrollHeight};
function showSources(ids=[]){dialog(`<h2>دانش و منابع دستیار</h2><p class="muted">خلاصه‌های تألیفی با لینک منبع؛ نه متن کامل مقالات و نه ادعای آموزش مدل.</p><div class="source-list">${KB.sources.filter(s=>!ids.length||ids.includes(s.id)).map(s=>`<details open><summary>${esc(s.title)}</summary><small>${esc(s.type)}</small><p>${esc(s.summary)}</p><p><b>حد اعتبار:</b> ${esc(s.limit)}</p><a href="${esc(s.url)}" target="_blank" rel="noopener">بازکردن منبع اصلی ↗</a></details>`).join('')}</div><p class="notice">این محتوا بازبینی تخصصی بالینی محصول را جایگزین نمی‌کند. اطلاعات علمیِ ماده با تأیید فرمول دقیق بازار ایران فرق دارد.</p>`)}
function localDay(){const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
function routineRoles(phase){return phase==='am'?['moisturize','protect']:['cleanse','moisturize']}
function routinePhase(phase){const d=state.dayLog[localDay()]||{},t=phase==='am'?'صبح':'شب',time=state.profile[phase==='am'?'amTime':'pmTime'];return `<section class="routine-half"><div class="row between"><h3>${phase==='am'?'☀':'☾'} ${t}</h3><small>${time?'زمان مطلوب: '+fa(time)+' دقیقه':'دو نقش پایه'}</small></div>${routineRoles(phase).map((r,i)=>{const w=owned(r),key=phase+'-'+r;return `<label class="routine-step"><input type="checkbox" data-step-check="${key}" ${d[key]?'checked':''}><span><b>${fa(i+1)}. ${roles[r]}</b><small>${esc(w?.name||'محصولی برای این نقش ثبت نشده')}</small></span></label>`}).join('')}${phase==='am'?'<small>محافظت از آفتاب فقط یک تیک صبح نیست؛ تجدید هنگام حضور بیرون و طبق برچسب را فراموش نکن.</small>':''}</section>`}
routine=function(){const p=state.profile,missing=basicRoles.filter(r=>!owned(r));return `<span class="eyebrow">مراقبت به اندازه وقت تو</span><h1>روتین قابل انجام من</h1><p class="muted">یک پیشنهاد پایه؛ محصول نامشخص یا درمان تخصصی را خودکار واردش نمی‌کنیم.</p>${!p.completedAt?'<div class="notice">پروفایل کامل نیست؛ این برنامه عمومی است. <button data-view="profile">تکمیل پروفایل</button></div>':''}${routinePhase('am')}${routinePhase('pm')}${p.medicationStatus==='yes'?`<section class="card"><h3>درمان فعلی؛ طبق دستور پزشک</h3><p>${esc(p.medications)}</p><small>زمان یا دفعات درمان را این اپ تعیین نمی‌کند.</small></section>`:''}${routineWarnings()}<section class="card"><h2>کمبودهای ولت من</h2>${missing.length?missing.map(r=>`<div class="step"><div><b>${roles[r]}</b><small>در ولت ثبت نشده یا رو به اتمام است.</small></div><button data-category-go="${r}">گزینه‌ها</button></div>`).join(''):'<p class="good">نقش‌های پایه را داری؛ خرید تازه الزاماً لازم نیست.</p>'}<button class="outline full" data-v8="basket">سبد محاسباتی در بودجه من</button></section><div class="row"><button data-v8="snapshot">ثبت وضعیت امروز</button><button data-v8="sources">منابع برنامه</button></div><p class="local-note">تیک‌ها در همین دستگاه ذخیره می‌شوند. زمان‌ها ترجیح تو هستند و مقدار مصرف را کوتاه نمی‌کنند.</p>`};
function routineWarnings(){const warnings=[];const p=state.profile;if(listify(p.currentSymptoms).some(x=>['severe','burn'].includes(x)))warnings.push('علائم تحریک ثبت کردی؛ قبل از اضافه‌کردن محصول، علت آن نیاز به بررسی دارد.');if(p.pregnancy&&p.pregnancy!=='no')warnings.push('وضعیت بارداری/شیردهی یا نامشخص بودن آن ثبت شده؛ فعال جدید بدون بررسی حرفه‌ای پیشنهاد نمی‌شود.');if(p.age==='under18')warnings.push('سن زیر ۱۸ ثبت شده؛ انتخاب مراقبت و درمان باید متناسب با سن بررسی شود.');const all=state.wallet.map(w=>({w,text:norm(w.name+' '+(w.inci||'')+' '+(w.active||''))})),ret=all.filter(x=>/retinol|tretinoin|adapalene|رتینول|رتینوئید|آداپالن|ترتینوئین/.test(x.text)),acid=all.filter(x=>/glycolic|salicylic|lacticacid|گلیکولیک|سالیسیلیک|لاکتیکاسید/.test(x.text));if(ret.length&&acid.length)warnings.push('در نام یا ترکیبات ثبت‌شده، رتینوئید و اسید لایه‌بردار دیده می‌شود. استفاده هم‌زمان ممکن است تحمل پوست را سخت‌تر کند؛ این یک هشدار اولیه است، نه اعلام تداخل قطعی همه فرمول‌ها.');if(p.pregnancy&&p.pregnancy!=='no'&&ret.length)warnings.push('رتینوئید در ولت شناسایی شد؛ پیش از مصرف در بارداری/اقدام، با پزشک بررسی کن.');const roleCounts={};state.wallet.filter(w=>w.remaining>0).forEach(w=>roleCounts[w.role]=(roleCounts[w.role]||0)+1);if(Object.values(roleCounts).some(n=>n>1))warnings.push('چند محصول هم‌نقش داری؛ برای روتین کوتاه لازم نیست همه را پشت سر هم استفاده کنی.');return warnings.length?'<div class="notice"><b>چیزهایی که باید بررسی کنیم</b><ul>'+warnings.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul></div>':''}
function walletEditor(id){const w=state.wallet.find(x=>x.id===id)||{id:'',name:'',role:'moisturize',remaining:100,time:'both',weekly:7,start:'',inci:'',active:'',prescribed:false};dialog(`<h2>${w.id?'ویرایش محصول':'محصول فعلی من'}</h2><form id="walletEditor" data-id="${esc(w.id)}"><label>نام دقیق محصول<input name="name" value="${esc(w.name)}" maxlength="220" required></label><label>نقش<select name="role">${Object.entries(roles).map(([k,v])=>`<option value="${k}" ${w.role===k?'selected':''}>${v}</option>`).join('')}</select></label><label>باقی‌مانده · درصد<input name="remaining" type="number" min="0" max="100" value="${w.remaining}" required></label><label>زمانی که الان استفاده می‌کنی<select name="time">${[['am','صبح'],['pm','شب'],['both','صبح و شب'],['variable','متغیر']].map(([k,v])=>`<option value="${k}" ${w.time===k?'selected':''}>${v}</option>`).join('')}</select></label><label>دفعات استفاده در هفته<input name="weekly" type="number" min="0" max="28" value="${w.weekly??7}"></label><label>شروع استفاده<input name="start" type="date" value="${esc(w.start||'')}"></label><label>ماده فعال و غلظت، اگر روی بسته نوشته شده<input name="active" value="${esc(w.active||'')}" placeholder="مثلاً Niacinamide 5%"></label><label>ترکیبات دقیق روی بسته<textarea name="inci" rows="3">${esc(w.inci||'')}</textarea></label><div class="choice-grid"><label><input type="checkbox" name="prescribed" ${w.prescribed?'checked':''}>پزشک این محصول را تجویز کرده</label></div><p class="notice">اطلاعات واردشده، ثبت خودت است و تأیید آزمایشگاهی یا فرمول بازار محسوب نمی‌شود. افزودن محصول موجود به ولت هزینه این ماه را تغییر نمی‌دهد.</p><button class="gold full">ذخیره در ولت</button></form>`)}
wallet=function(){return `<span class="eyebrow">حافظه شخصی پوست من</span><div class="row between"><h1>ولت من</h1><button class="gold" data-v8="add-wallet">＋ محصول</button></div><section class="card"><div class="expense-grid"><div><small>محصول ثبت‌شده</small><b>${fa(state.wallet.length)}</b></div><div><small>خرج این ماه</small><b>${fa(spent())} تومان</b></div></div>${state.wallet.length?state.wallet.map(w=>`<div class="step"><div style="flex:1"><b>${esc(w.name)}</b><small>${roles[w.role]||'مراقبت'} · ${fa(w.remaining)}٪ باقی‌مانده${w.prescribed?' · تجویزشده':''}</small><div class="row"><button data-v8-wallet="${esc(w.id)}">ویرایش</button><button data-consume="${esc(w.id)}">۱۰٪ مصرف</button><button data-v8-outcome="${esc(w.id)}">ثبت نتیجه</button><button data-remove="${esc(w.id)}" class="remove" aria-label="حذف محصول">×</button></div></div></div>`).join(''):'<div class="empty">با محصولی که همین حالا داری شروع کن.</div>'}</section><section class="card"><h2>عکس شروع و روند من</h2><p class="muted">عکس‌ها اختیاری و برای مقایسه شخصی‌اند؛ تشخیص یا اثبات اثر محصول نیستند.</p><button data-v8="baseline">${state.baselinePhoto?'تغییر عکس شروع':'ثبت عکس شروع'}</button>${state.baselinePhoto?`<div class="photo-pair" style="margin-top:14px"><figure style="margin:0"><img src="${esc(state.baselinePhoto.photo)}" alt="عکس شروع"><figcaption>شروع · ${new Date(state.baselinePhoto.date).toLocaleDateString('fa-IR')}</figcaption></figure>${state.outcomes.filter(o=>o.photo).length?`<figure style="margin:0"><img src="${esc(state.outcomes.filter(o=>o.photo).at(-1).photo)}" alt="آخرین عکس ثبت‌شده"><figcaption>آخرین ثبت شخصی</figcaption></figure>`:''}</div>`:''}</section><section class="card"><h2>تجربه‌های من</h2>${state.outcomes.length?state.outcomes.slice().reverse().map(o=>`<div class="step">${o.photo?`<img class="thumb" src="${esc(o.photo)}" alt="عکس پیگیری">`:''}<div style="flex:1"><b>${esc(o.name)}</b><small>رضایت ${fa(o.rating)} از ۵ · ${new Date(o.date).toLocaleDateString('fa-IR')}</small><p>${esc(o.note||'')}</p>${o.symptom?`<small>وضعیت: ${esc(o.symptom)}</small>`:''}<button data-delete-outcome="${esc(o.id||o.date)}" class="remove">حذف ثبت</button></div></div>`).join(''):'<p class="muted">نتیجه مثبت، بی‌تفاوتی یا واکنش نامطلوب را ثبت کن.</p>'}</section><section class="card"><h2>خریدهای ثبت‌شده این ماه</h2>${state.purchases.map((x,i)=>({x,i})).filter(({x})=>x.month===month()).map(({x,i})=>`<div class="ledger-line row between"><span>${esc(catalog.find(p=>p.id===x.productId)?.nameFa||'خرید ثبت‌شده')}<br>${fa(x.price)} تومان</span><button data-expense-delete="${i}" class="remove">اصلاح / حذف</button></div>`).join('')||'<p class="muted">خریدی ثبت نشده.</p>'}</section><section class="card"><h2>محصولات ناشناخته</h2>${state.intakes.map(x=>`<details><summary>${esc(x.name)} · نیازمند بررسی</summary><p>بارکد: ${esc(x.barcode||'ثبت نشده')}</p><p>${esc(x.inci||'ترکیبات هنوز وارد نشده')}</p>${safeUrl(x.url)?`<a href="${esc(safeUrl(x.url))}" target="_blank" rel="noopener">صفحه محصول</a>`:''}${x.photo?`<img class="thumb" src="${esc(x.photo)}" alt="بسته‌بندی">`:''}<div class="row"><button data-intake-edit="${esc(x.id)}">تکمیل مشخصات</button><button data-intake-delete="${esc(x.id)}" class="remove">حذف</button></div></details>`).join('')||'<p class="muted">موردی در انتظار تکمیل نیست.</p>'}<button data-action="intake">ثبت محصول ناشناخته</button></section><section class="card"><h2>تصمیم‌ها و پیگیری</h2>${state.decisions.slice(-10).reverse().map(d=>`<p>${esc(d.name)} · ${esc(d.action)} <small>${new Date(d.date).toLocaleDateString('fa-IR')}</small></p>`).join('')||'<p class="muted">بعد از بررسی محصولات، تصمیم‌ها اینجا می‌مانند.</p>'}<p class="muted">${fa(state.snapshots.length)} وضعیت روزانه ثبت شده · ${fa(Object.keys(state.dayLog).length)} روز با ثبت مراحل</p></section><button class="outline full" data-v8="backup">پشتیبان گرفتن از اطلاعات من</button>`};
function outcomeEditor(id){const w=state.wallet.find(x=>x.id===id);if(!w)return;dialog(`<h2>بعد از مصرف چه حسی داشتی؟</h2><p>${esc(w.name)}</p><form id="v8Outcome" data-id="${esc(w.id)}"><label>رضایت کلی<select name="rating">${[1,2,3,4,5].map(n=>`<option value="${n}" ${n===3?'selected':''}>${fa(n)} از ۵</option>`).join('')}</select></label><label>وضعیت امروز<select name="symptom"><option>تغییر خاصی ندیدم</option><option>احساس بهتر / قابل تحمل</option><option>خشکی بیشتر</option><option>قرمزی یا خارش</option><option>سوزش یا واکنش جدید</option></select></label><label>یادداشت<textarea name="note" rows="3" maxlength="1500" placeholder="چه چیزی بهتر یا بدتر شد؟ هم‌زمان محصول دیگری هم عوض کردی؟"></textarea></label><label>عکس اختیاری<input type="file" accept="image/*" name="photo"></label><p class="muted">نور، فاصله و زاویه مشابه کمک می‌کند عکس‌ها قابل مقایسه‌تر شوند.</p><button class="gold full">ثبت تجربه من</button></form>`)}
function metaEditor(id){const p=catalog.find(x=>x.id===id),m=state.productMeta[id]||{};dialog(`<h2>مشخصات روی بسته</h2><p>${esc(p.nameFa)}</p><form id="productMeta" data-id="${id}"><label>فهرست کامل ترکیبات INCI<textarea name="inci" rows="5">${esc(m.inci||'')}</textarea></label><label>بافت درج‌شده یا تجربه‌شده<select name="texture"><option value="">نامشخص</option><option value="light" ${m.texture==='light'?'selected':''}>سبک</option><option value="rich" ${m.texture==='rich'?'selected':''}>غلیظ</option></select></label><label>عطر در ترکیبات / برچسب<select name="fragrance"><option value="">نامشخص</option><option value="yes" ${m.fragrance==='yes'?'selected':''}>دارد</option><option value="no" ${m.fragrance==='no'?'selected':''}>طبق برچسب بدون عطر</option></select></label><label>لینک منبع یا سازنده<input name="url" type="url" value="${esc(m.url||'')}"></label><p class="notice">ثبت خودت با تأیید مستقل فرق دارد؛ این فرم وضعیت تأیید فرمول را عوض نمی‌کند.</p><button class="gold full">ذخیره مشخصات</button></form>`)}
showProduct=function(id){const p=catalog.find(x=>x.id===id);if(!p)return;state.recentQuestion={productId:id};const q=price(p),f=fit(p),g=productGate(p),same=owned(p.role);const decision=same?'فعلاً خرید تکراری اولویت ندارد':g.length?'اول اطلاعات را کامل کنیم':!q?.fresh?'اول قیمت فعلی را مشخص کن':q.value>availableBudget()?'از بودجه این خرید بیشتر است':'برای بررسی بیشتر در بودجه جا می‌شود';const alternatives=catalog.filter(x=>x.role===p.role&&x.id!==id).sort((a,b)=>fit(b).score-fit(a).score).slice(0,3);dialog(`<span class="eyebrow">تصمیم قبل از خرید</span><h2>${esc(p.nameFa)}</h2><span class="phase-label incomplete">${decision}</span><p style="margin-top:12px">${priceText(p)}</p><ul>${f.reasons.map(r=>'<li>'+esc(r)+'</li>').join('')}</ul><div class="notice"><b>چیزی که هنوز نمی‌دانیم</b><ul>${g.map(r=>'<li>'+esc(r)+'</li>').join('')||'<li>اثر واقعی برای خودت فقط با پیگیری روشن می‌شود.</li>'}</ul></div><details><summary>مشخصات و ترکیبات ثبت‌شده</summary><p>نوع پوست درج‌شده: ${esc((p.skinTypes||[]).map(t=>skins[t]||t).join('، '))}</p><p>${esc(state.productMeta[id]?.inci||'ترکیبات کامل در دسترس نیست')}</p><button data-meta="${id}">تکمیل از روی بسته</button></details><div class="links">${(p.sources||[]).filter(s=>safeUrl(s.url)).map(s=>`<a href="${esc(safeUrl(s.url))}" target="_blank" rel="noopener">${esc(s.publisher||s.title)}</a>`).join('')}</div><div class="row"><button data-price="${id}">ثبت قیمت</button><button data-owned="${id}">این را دارم</button><button data-bought="${id}" class="gold">خرید انجام‌شده را ثبت کن</button><button data-wait="${id}">فعلاً نمی‌خرم</button></div><p class="source-tag">«ثبت خرید» گزارش انتخاب خودت است؛ تأیید پزشکی یا توصیه قطعی خرید نیست.</p><h3 style="margin-top:22px">جایگزین‌های هم‌نقش</h3>${alternatives.map(x=>`<div class="step"><div><b>${esc(x.nameFa)}</b><small>${quoteSummary(x)}</small></div><button data-detail="${x.id}">مقایسه</button></div>`).join('')}<button class="outline full" data-chat-kind="compare" data-chat-id="${id}">نظر دستیار درباره جایگزین‌ها</button>`)};
function backup(){const blob=new Blob([JSON.stringify({version:8,exportedAt:new Date().toISOString(),state},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='BeautyWallet-v8-My-Backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000)}
function safePhoto(s){return typeof s==='string'&&/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(s)?s:''}
function validateBackup(raw){if(!raw||![7,8].includes(raw.version)||!raw.state||typeof raw.state.profile!=='object')throw Error('این فایل پشتیبان معتبر نیست.');const s=raw.state;for(const key of ['wallet','outcomes','purchases','decisions','chat','intakes','likes'])if(!Array.isArray(s[key]))throw Error('ساختار فایل ناقص است.');if(s.purchases.some(x=>!Number.isFinite(x.price)||x.price<0))throw Error('مبلغ نامعتبر در فایل وجود دارد.');const result={...structuredClone(initial),...s};result.profile={...PREF,...s.profile};if(!Number.isFinite(num(result.profile.budget))||num(result.profile.budget)<0)throw Error('بودجه فایل معتبر نیست.');result.profile.budget=num(result.profile.budget);for(const k of ['outcomes','intakes'])result[k]=result[k].map(x=>({...x,photo:safePhoto(x.photo)}));if(result.baselinePhoto)result.baselinePhoto={...result.baselinePhoto,photo:safePhoto(result.baselinePhoto.photo)};result.chat=result.chat.map(x=>({...x,role:x.role==='user'?'user':'assistant',text:String(x.text||''),sources:listify(x.sources).filter(id=>KB.sources.some(s=>s.id===id)),buttons:[]}));for(const k of ['feedback','snapshots','quoteHistory'])result[k]=Array.isArray(result[k])?result[k]:[];for(const k of ['dayLog','productMeta','prices'])result[k]=result[k]&&typeof result[k]==='object'&&!Array.isArray(result[k])?result[k]:{};return result}
function restoreDialog(){dialog('<h2>بازیابی اطلاعات خودت</h2><p>فایل پشتیبانی که از BeautyWallet گرفتی انتخاب کن.</p><input id="v8Restore" type="file" accept="application/json"><p class="notice">بازیابی بعد از تأیید، جایگزین اطلاعات فعلی همین مرورگر می‌شود.</p>');$('#v8Restore').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>20*1024*1024)throw Error('فایل بزرگ‌تر از ۲۰ مگابایت است.');const restored=validateBackup(JSON.parse(await file.text()));if(!confirm('اطلاعات فعلی با این پشتیبان جایگزین شود؟'))return;const previous=state;state=restored;if(!persist()){state=previous;return}wizardDraft=null;$('#modal').close();go('home');toast('اطلاعاتت برگشت.')}catch(err){toast(err.message||'فایل قابل بازیابی نیست.')}}}
function finishProfile(){const p=readDraft(),missing=missingProfile(p);if(missing.length){const step=FORM.findIndex(s=>s.fields.some(f=>f.id===missing[0]));wizardStep=Math.max(0,step);render();$('#profileError').textContent='این بخش هنوز کامل نیست؛ «نمی‌دانم» هم پاسخ قابل قبولی است.';return}const now=new Date().toISOString();state.profile={...p,budget:num(p.budget),purchaseCap:p.purchaseCap===''?'':num(p.purchaseCap),shipping:num(p.shipping)||0,time:num(p.amTime)+num(p.pmTime),avoid:p.allergies||'',completedAt:p.completedAt||now,updatedAt:now};state.profileDraft=null;if(!persist())return;wizardDraft=null;wizardStep=0;go('home');toast('پروفایلت ذخیره شد؛ دفعه بعد از اول نمی‌پرسم.')}
function switchWizard(step){if($('#profileWizard'))saveDraft($('#profileWizard'));wizardStep=Math.max(0,Math.min(FORM.length-1,Number(step)));render();window.scrollTo(0,0)}
render=function(){oldRender();document.body.dataset.route=route;$('#main').classList.toggle('home-main',route==='home');updateHome();if(route==='profile'&&$('#profileWizard'))$('#profileWizard').onsubmit=e=>{e.preventDefault();saveDraft(e.target);const error=wizardValidation();if(error){$('#profileError').textContent=error;return}if(wizardStep<FORM.length-1)switchWizard(wizardStep+1);else finishProfile()};if(route==='assistant'&&$('#chat'))$('#chat').scrollTop=$('#chat').scrollHeight};
document.addEventListener('input',e=>{if(e.target.closest('#profileWizard'))saveDraft($('#profileWizard'))});
document.addEventListener('change',e=>{if(e.target.closest('#profileWizard')){const el=e.target;if(el.type==='checkbox'&&el.name!=='consent'){const siblings=[...document.querySelectorAll('#profileWizard input[name="'+el.name+'"]')];if(el.checked&&['none','unknown'].includes(el.value))siblings.filter(x=>x!==el).forEach(x=>x.checked=false);else if(el.checked)siblings.filter(x=>['none','unknown'].includes(x.value)).forEach(x=>x.checked=false)}saveDraft($('#profileWizard'))}if(e.target.dataset.stepCheck){const day=localDay();state.dayLog[day]=state.dayLog[day]||{};state.dayLog[day][e.target.dataset.stepCheck]=e.target.checked;persist()}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;
 if(d.wizardStep!==undefined)switchWizard(d.wizardStep);if(d.wizardPrev!==undefined)switchWizard(wizardStep-1);
 if(d.v8Wallet)walletEditor(d.v8Wallet);if(d.v8Outcome)outcomeEditor(d.v8Outcome);if(d.meta){$('#modal').close();metaEditor(d.meta)}
 if(d.chatKind){if($('#modal').open)$('#modal').close();const k=d.chatKind,id=d.chatId;if(k==='view')go(id);if(k==='profile'){wizardStep=Number(id);go('profile')}if(k==='ask')ask(id);if(k==='sources')showSources(id?id.split(','):[]);if(k==='product')showProduct(id);if(k==='intake')intake();if(k==='compare'){const p=catalog.find(x=>x.id===id);if(p){const r=comparisonReply(p);state.chat.push(r);state.recentQuestion={productId:id};persist();go('assistant')}}if(k==='budget'){const value=num(id);if(Number.isFinite(value)&&value>=0){state.profile.budget=value;state.profile.updatedAt=new Date().toISOString();wizardDraft=null;state.profileDraft=null;state.chat.push(makeReply('بودجه جدیدت ثبت شد',fa(value)+' تومان سقف ماهانه جدید است. محاسبات بعدی از همین مبلغ استفاده می‌کنند.','اگر خواستی سبدت را دوباره بررسی کنیم.',[],[{label:'بررسی بودجه جدید',kind:'ask',id:'با بودجه‌ام چی بخرم؟'}]));persist();go('assistant')}}}
 if(d.feedback){state.feedback=state.feedback.filter(f=>f.id!==d.feedback);state.feedback.push({id:d.feedback,rating:d.rating,date:new Date().toISOString()});persist();render();toast('بازخوردت ثبت شد؛ این ثبت به معنی آموزش مدل نیست.')}
 if(d.expenseDelete!==undefined&&confirm('این ثبت خرید حذف شود؟ بودجه دوباره محاسبه می‌شود.')){state.purchases.splice(Number(d.expenseDelete),1);persist();render()}
 if(d.deleteOutcome&&confirm('این نتیجه و عکس همراهش حذف شود؟')){state.outcomes=state.outcomes.filter(x=>(x.id||x.date)!==d.deleteOutcome);persist();render()}
 if(d.intakeDelete&&confirm('این محصول ناشناخته حذف شود؟')){state.intakes=state.intakes.filter(x=>x.id!==d.intakeDelete);persist();render()}
 if(d.intakeEdit){const x=state.intakes.find(x=>x.id===d.intakeEdit);dialog(`<h2>تکمیل محصول ناشناخته</h2><form id="intakeEdit" data-id="${esc(x.id)}"><label>نام<input name="name" value="${esc(x.name)}" required></label><label>بارکد<input name="barcode" value="${esc(x.barcode||'')}" inputmode="numeric"></label><label>لینک<input name="url" value="${esc(x.url||'')}" type="url"></label><label>ترکیبات<textarea name="inci" rows="5">${esc(x.inci||'')}</textarea></label><button class="gold full">ذخیره مشخصات</button></form>`)}
 if(d.v8==='add-wallet')walletEditor('');if(d.v8==='sources')showSources();if(d.v8==='backup')backup();if(d.v8==='restore')restoreDialog();if(d.v8==='clear-chat'&&confirm('گفتگوهای این مرورگر پاک شوند؟')){state.chat=[];state.recentQuestion=null;persist();render()}
 if(d.v8==='erase'&&confirm('پروفایل، ولت، گفتگو و عکس‌های این نسخه از همین مرورگر حذف شوند؟ این کار برگشت‌پذیر نیست مگر پشتیبان داشته باشی.')){try{localStorage.removeItem(KEY)}catch{}location.reload()}
 if(d.v8==='snapshot'){state.snapshots.push({date:new Date().toISOString(),skinToday:state.profile.skinToday,wallet:state.wallet.map(x=>({id:x.id,name:x.name,remaining:x.remaining})),completedSteps:{...(state.dayLog[localDay()]||{})}});persist();toast('وضعیت امروز ثبت شد.')}
 if(d.v8==='basket'){const r=budgetReply();dialog(`<h2>${esc(r.title)}</h2><p style="white-space:pre-wrap">${esc(r.text)}</p><p class="notice">${esc(r.action)}</p><button data-view="products" onclick="document.getElementById('modal').close()">دیدن گزینه‌ها</button>`)}
 if(d.v8==='baseline'){dialog('<h2>عکس شروع من</h2><p>بدون فیلتر، با نور یکنواخت و بدون آرایش سنگین ثبت کن. عکس برای مقایسه است، نه تشخیص.</p><form id="baselineForm"><label>عکس شروع<input name="photo" type="file" accept="image/*" required></label><div class="choice-grid"><label><input type="checkbox" name="consent" required>این عکس روی همین دستگاه ذخیره شود</label></div><button class="gold full">ذخیره عکس</button></form>')}
});
document.addEventListener('submit',async e=>{const form=e.target;if(!['walletEditor','v8Outcome','productMeta','baselineForm','intakeEdit'].includes(form.id))return;e.preventDefault();const button=form.querySelector('button[type="submit"],button.gold'),fd=new FormData(form),o=Object.fromEntries(fd);if(button)button.disabled=true;try{
 if(form.id==='walletEditor'){const id=form.dataset.id||uid(),prev=state.wallet.find(x=>x.id===id),matched=catalog.find(p=>norm(p.nameFa)===norm(o.name)),w={...prev,id,productId:prev?.productId||matched?.id||null,name:o.name.trim(),role:o.role,remaining:Number(o.remaining),time:o.time,weekly:Number(o.weekly),start:o.start,active:o.active,inci:o.inci,prescribed:fd.has('prescribed')};if(!w.name||!Number.isFinite(w.remaining)||w.remaining<0||w.remaining>100)throw Error('نام و مقدار باقی‌مانده را بررسی کن.');if(prev)state.wallet=state.wallet.map(x=>x.id===id?w:x);else state.wallet.push(w)}
 if(form.id==='v8Outcome'){const w=state.wallet.find(x=>x.id===form.dataset.id),photo=await photoData(o.photo?.size?o.photo:null);state.outcomes.push({id:uid(),name:w.name,productId:w.productId||w.id,rating:Number(o.rating),symptom:o.symptom,note:o.note,photo,date:new Date().toISOString()})}
 if(form.id==='productMeta')state.productMeta[form.dataset.id]={inci:o.inci,texture:o.texture,fragrance:o.fragrance,url:o.url,provenance:'user_entered_unverified',date:new Date().toISOString()};
 if(form.id==='baselineForm'){if(!fd.has('consent'))throw Error('برای ذخیره عکس رضایت لازم است.');const photo=await photoData(o.photo?.size?o.photo:null);if(!photo)throw Error('یک عکس انتخاب کن.');state.baselinePhoto={photo,date:new Date().toISOString()}}
 if(form.id==='intakeEdit'){const code=String(o.barcode||'').replace(/[۰-۹]/g,c=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(c));if(code&&!validGTIN(code))throw Error('ساختار یا رقم کنترل بارکد درست نیست.');state.intakes=state.intakes.map(x=>x.id===form.dataset.id?{...x,name:o.name,barcode:code,url:o.url,inci:o.inci}:x)}
 if(persist()){$('#modal').close();render();toast('ذخیره شد.')}
 }catch(err){toast(err.message||'ذخیره انجام نشد.')}finally{if(button)button.disabled=false}});
photoData=async function(file){if(!file)return '';if(!file.type.startsWith('image/'))throw Error('لطفاً فایل عکس انتخاب کن.');if(file.size>12*1024*1024)throw Error('عکس باید کمتر از ۱۲ مگابایت باشد.');let img;if(typeof createImageBitmap==='function'){try{img=await createImageBitmap(file)}catch{}}if(!img){img=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=()=>reject(Error('عکس خوانده نشد.'));reader.onload=()=>{const image=new Image();image.onload=()=>resolve(image);image.onerror=()=>reject(Error('این قالب عکس پشتیبانی نمی‌شود؛ JPG یا PNG انتخاب کن.'));image.src=reader.result};reader.readAsDataURL(file)})}const w=img.width||img.naturalWidth,h=img.height||img.naturalHeight;if(!w||!h)throw Error('ابعاد عکس معتبر نیست.');const c=document.createElement('canvas'),ratio=Math.min(1,640/Math.max(w,h));c.width=Math.max(1,Math.round(w*ratio));c.height=Math.max(1,Math.round(h*ratio));c.getContext('2d').drawImage(img,0,0,c.width,c.height);if(img.close)img.close();return c.toDataURL('image/jpeg',.75)};
